const listShipments = `-- name: ListShipments :many
SELECT s.id, s.public_id, s.awb, s.reference_number, s.current_status, s.status_changed_at,
       s.payment_mode, s.piece_count, s.chargeable_weight_grams, s.currency,
       s.total_amount_minor, s.cod_amount_minor, s.origin_pincode, s.destination_pincode,
       s.promised_delivery_at, s.booked_at, s.created_at,
       c.public_id AS customer_public_id, c.code AS customer_code, c.name AS customer_name,
       sv.code AS service_code, sv.name AS service_name,
       ob.code AS origin_branch_code, db.code AS destination_branch_code,
       COALESCE(rac.contact_name, ras.contact_name, '') AS recipient_name,
       COALESCE(rac.city_name, ras.city_name, '') AS recipient_city
FROM shipments s
JOIN customers c ON c.id = s.customer_id
JOIN courier_services sv ON sv.id = s.courier_service_id
LEFT JOIN operating_units ob ON ob.id = s.origin_branch_id
LEFT JOIN operating_units db ON db.id = s.destination_branch_id
LEFT JOIN shipment_address_snapshots ras ON ras.shipment_id = s.id AND ras.role = 'RECIPIENT'
LEFT JOIN LATERAL (
    SELECT contact_name, city_name
    FROM shipment_address_corrections
    WHERE shipment_id = s.id AND role = 'RECIPIENT'
    ORDER BY sequence DESC LIMIT 1
) rac ON true
WHERE s.organization_id = $1
  AND ($2::text[] IS NULL OR s.current_status = ANY($2::text[]))
  AND ($3::bigint IS NULL OR s.customer_id = $3)
  AND ($4::bigint IS NULL OR s.courier_service_id = $4)
  AND ($5::text IS NULL OR s.payment_mode = $5)
  AND ($6::timestamptz IS NULL OR s.created_at >= $6)
  AND ($7::timestamptz IS NULL OR s.created_at < $7)
  AND ($8::text IS NULL OR s.origin_pincode = $8)
  AND ($9::text IS NULL OR s.destination_pincode = $9)
  AND ($10::text IS NULL
       OR s.awb LIKE upper($10) || '%'
       OR s.reference_number = $10)
  AND ($11::bigint[] IS NULL
       OR s.origin_branch_id = ANY($11::bigint[])
       OR s.destination_branch_id = ANY($11::bigint[])
       OR s.booking_unit_id = ANY($11::bigint[]))
  AND ($12::bigint[] IS NULL OR s.customer_id = ANY($12::bigint[]))
  AND ($13::timestamptz IS NULL
       OR (s.created_at, s.id) < ($13::timestamptz, $14::bigint))
ORDER BY s.created_at DESC, s.id DESC
LIMIT $15
`

type ListShipmentsParams struct {
	OrganizationID     int64
	Statuses           []string
	CustomerID         *int64
	CourierServiceID   *int64
	PaymentMode        *string
	BookedFrom         *time.Time
	BookedTo           *time.Time
	OriginPincode      *string
	DestinationPincode *string
	Search             *string
	ScopedUnitIds      []int64
	CustomerIds        []int64
	CursorCreatedAt    *time.Time
	CursorID           int64
	RowLimit           int32
}

type ListShipmentsRow struct {
	ID                    int64
	PublicID              string
	Awb                   string
	ReferenceNumber       *string
	CurrentStatus         string
	StatusChangedAt       time.Time
	PaymentMode           string
	PieceCount            int32
	ChargeableWeightGrams int32
	Currency              string
	TotalAmountMinor      int64
	CodAmountMinor        int64
	OriginPincode         string
	DestinationPincode    string
	PromisedDeliveryAt    *time.Time
	BookedAt              time.Time
	CreatedAt             time.Time
	CustomerPublicID      string
	CustomerCode          string
	CustomerName          string
	ServiceCode           string
	ServiceName           string
	OriginBranchCode      *string
	DestinationBranchCode *string
	RecipientName         string
	RecipientCity         string
}

// ListShipments is the operations console's primary query.
//
// It is keyset paginated on (created_at, id): the cursor predicate keeps the
// plan on shipments_org_created_idx no matter how deep the caller pages, unlike
// OFFSET which degrades linearly.
func (q *Queries) ListShipments(ctx context.Context, arg ListShipmentsParams) ([]ListShipmentsRow, error) {
	rows, err := q.db.Query(ctx, listShipments,
		arg.OrganizationID,
		arg.Statuses,
		arg.CustomerID,
		arg.CourierServiceID,
		arg.PaymentMode,
		arg.BookedFrom,
		arg.BookedTo,
		arg.OriginPincode,
		arg.DestinationPincode,
		arg.Search,
		arg.ScopedUnitIds,
		arg.CustomerIds,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListShipmentsRow{}
	for rows.Next() {
		var i ListShipmentsRow
		if err := rows.Scan(
			&i.ID,
			&i.PublicID,
			&i.Awb,
			&i.ReferenceNumber,
			&i.CurrentStatus,
			&i.StatusChangedAt,
			&i.PaymentMode,
			&i.PieceCount,
			&i.ChargeableWeightGrams,
			&i.Currency,
			&i.TotalAmountMinor,
			&i.CodAmountMinor,
			&i.OriginPincode,
			&i.DestinationPincode,
			&i.PromisedDeliveryAt,
			&i.BookedAt,
			&i.CreatedAt,
			&i.CustomerPublicID,
			&i.CustomerCode,
			&i.CustomerName,
			&i.ServiceCode,
			&i.ServiceName,
			&i.OriginBranchCode,
			&i.DestinationBranchCode,
			&i.RecipientName,
			&i.RecipientCity,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

